[metadata] {"filePath": "/workspace/repo/metadata-ingestion/src/datahub/entrypoints.py", "oldString": "@datahub.command(cls=_make_agent_aware_command("INIT_AGENT_CONTEXT.md"))", "newString": "def _derive_frontend_url_from_host(host_value: str) -> str:
    """Derive the DataHub frontend URL from a GMS host for browser SSO login.

    - Local development (``localhost``/``127.0.0.1`` on port 8080) → port 9002.
    - DataHub Cloud URLs ending in ``/gms`` → strip the ``/gms`` suffix.
    """
    if "localhost" in host_value or "127.0.0.1" in host_value:
        return host_value.replace(":8080", ":9002")
    if host_value.endswith("/gms"):
        return host_value[: -len("/gms")]
    return host_value


